<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#11100e">
  <title>Administración de eventos — El Café de los Poetas Muertos</title>
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet">
  <style>
    :root{--ink:#11100e;--panel:#191714;--cream:#f5efdf;--muted:#b9b09e;--gold:#d6ad59;--red:#c77d67;--line:#38332b;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--cream);font:15px/1.6 var(--sans)}button,input,textarea,select{font:inherit}.wrap{width:min(1050px,calc(100% - 38px));margin:auto}header{background:#151310;border-bottom:1px solid var(--line)}.nav{min-height:68px;display:flex;justify-content:space-between;align-items:center;gap:15px}.brand{font:700 1rem var(--serif);text-decoration:none;display:flex;align-items:center;gap:11px}.brand img{width:38px;height:38px;border-radius:50%;object-fit:cover;border:1px solid var(--gold)}.nav a:last-child{color:var(--gold);font-size:.84rem}.hero{padding:36px 0 25px}.eyebrow{color:var(--gold);font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700}.hero h1{font:600 clamp(2rem,5vw,3rem) var(--serif);margin:6px 0}.panel{background:var(--panel);border:1px solid var(--line);padding:25px;margin-bottom:23px}.panel h2{font:600 1.45rem var(--serif);margin:0 0 16px}.login-box{max-width:430px;margin:45px auto}.field{margin-bottom:14px}.field label{display:block;color:var(--gold);font-size:.8rem;margin-bottom:5px}.field input,.field textarea,.field select{display:block;width:100%;background:#100f0d;color:var(--cream);border:1px solid #454036;padding:11px 12px}.field textarea{min-height:120px;resize:vertical}.field input:focus,.field textarea:focus,.field select:focus{outline:2px solid var(--gold);outline-offset:1px}.help{color:var(--muted);font-size:.75rem}.button{border:1px solid var(--gold);background:var(--gold);color:var(--ink);font-weight:700;padding:11px 16px;cursor:pointer}.button.secondary{background:transparent;color:var(--gold)}.button.danger{border-color:#75453b;background:transparent;color:var(--red)}.button:disabled{opacity:.55;cursor:wait}.actions{display:flex;gap:9px;flex-wrap:wrap}.notice{min-height:22px;color:var(--gold);font-size:.85rem;margin:10px 0}.hidden{display:none!important}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.wide{grid-column:1/-1}.image-preview{display:block;max-width:280px;max-height:180px;object-fit:cover;margin:10px 0;border:1px solid var(--line)}.event-list{display:grid;gap:13px}.event{padding:18px;background:#141310;border:1px solid #332f27}.event-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.event h3{font:600 1.25rem var(--serif);margin:0}.event-meta{color:var(--muted);font-size:.8rem;margin:5px 0 12px}.badge{display:inline-block;padding:3px 9px;border:1px solid #7a653d;color:var(--gold);font-size:.7rem;text-transform:uppercase;letter-spacing:.07em}.badge.finished{border-color:#63453d;color:#dc9b88}.event-actions{display:flex;flex-wrap:wrap;gap:8px;margin:11px 0}.event-actions .button{font-size:.78rem;padding:8px 11px}.attendees{margin-top:15px;overflow-x:auto}.attendees table{width:100%;border-collapse:collapse;font-size:.8rem}.attendees th,.attendees td{border-bottom:1px solid var(--line);text-align:left;padding:8px}.attendees th{color:var(--gold)}.empty{color:var(--muted);padding:15px;background:#141310}.event-image{width:100%;max-width:220px;max-height:130px;object-fit:cover;float:right;margin:0 0 10px 15px}.site-footer{border-top:1px solid var(--line);padding:20px 0;color:var(--muted);font-size:.8rem}.site-footer a{color:var(--gold);text-decoration:none}
    @media(max-width:650px){.wrap{width:calc(100% - 28px)}.panel{padding:19px}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.event-head{flex-direction:column}}
  </style>
</head>
<body>
  <header><nav class="nav wrap"><a class="brand" href="index.php"><img src="images/images%20(1).jfif" alt=""><span>El Café de los Poetas Muertos</span></a><a href="eventos.php">Ver página pública ↗</a></nav></header>
  <main class="wrap"><div class="hero"><span class="eyebrow">Panel privado</span><h1>Administración de eventos</h1></div>
    <section class="panel login-box" id="login-panel"><h2>Iniciar sesión</h2><form id="login-form"><div class="field"><label for="password">Contraseña de administrador</label><input id="password" type="password" autocomplete="current-password" required></div><button class="button" type="submit">Entrar</button><p class="notice" id="login-notice" role="status"></p></form><p class="help">La contraseña se configura en el servidor y no se guarda en esta página.</p></section>
    <div id="dashboard" class="hidden">
      <section class="panel"><h2 id="form-title">Crear evento</h2><form id="event-form"><input id="edit-id" type="hidden"><input id="existing-image" type="hidden">
        <div class="form-grid"><div class="field"><label for="event-name">Nombre del evento</label><input id="event-name" maxlength="120" required></div>
          <div class="field"><label for="event-date">Fecha y hora</label><input id="event-date" type="datetime-local" required></div>
          <div class="field"><label for="capacity">Cupo máximo</label><input id="capacity" type="number" min="1" max="10000" required></div>
          <div class="field"><label for="event-status">Estado</label><select id="event-status"><option value="active">Abierto a registros</option><option value="finished">Finalizado / registro cerrado</option></select></div>
          <div class="field wide"><label for="description">Descripción</label><textarea id="description" maxlength="5000" required placeholder="Describe el encuentro, actividades, requisitos o información útil."></textarea></div>
          <div class="field wide"><label for="event-image">Imagen del evento (JPG, PNG o WEBP; máximo 5 MB)</label><input id="event-image" type="file" accept="image/jpeg,image/png,image/webp"><img id="image-preview" class="image-preview hidden" alt="Vista previa de la imagen"></div>
        </div><div class="actions"><button class="button" id="save-event" type="submit">Guardar evento</button><button class="button secondary hidden" type="button" id="cancel-edit">Cancelar edición</button></div><p class="notice" id="event-notice" role="status"></p>
      </form></section>
      <section class="panel"><div class="event-head"><h2>Eventos y registros</h2><div class="actions"><button class="button secondary" id="refresh" type="button">Actualizar</button><button class="button secondary" id="logout" type="button">Cerrar sesión</button></div></div><div class="event-list" id="event-list"><p class="empty">Cargando…</p></div></section>
    </div>
  </main>
  <footer class="site-footer"><div class="wrap">Los registros contienen datos personales. Mantén el acceso al panel y los PDF bajo control. · <a href="index.php">Página principal</a></div></footer>
  <script>
    const loginPanel=document.getElementById('login-panel'), dashboard=document.getElementById('dashboard');
    const loginNotice=document.getElementById('login-notice'), eventNotice=document.getElementById('event-notice');
    const eventList=document.getElementById('event-list'), eventForm=document.getElementById('event-form');
    const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const apiBase=['localhost','127.0.0.1'].includes(location.hostname)?'http://127.0.0.1:8000':''; const dateText=value=>new Intl.DateTimeFormat('es-MX',{dateStyle:'long',timeStyle:'short'}).format(new Date(value));
    async function api(url,options={}){const response=await fetch(`${apiBase}${url}`,{...options,credentials:'include',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});let data={};if(response.status!==204){data=await response.json().catch(()=>({}));}if(!response.ok)throw new Error(data.error||'Ocurrió un error.');return data;}
    async function showDashboard(){loginPanel.classList.add('hidden');dashboard.classList.remove('hidden');await loadEvents();}
    async function checkSession(){try{await api('/api/admin/events');await showDashboard()}catch{loginPanel.classList.remove('hidden');dashboard.classList.add('hidden')}}
    document.getElementById('login-form').addEventListener('submit',async e=>{e.preventDefault();loginNotice.textContent='Validando…';try{await api('/api/login',{method:'POST',body:JSON.stringify({password:document.getElementById('password').value})});document.getElementById('password').value='';loginNotice.textContent='';await showDashboard()}catch(error){loginNotice.textContent=error.message}});
    async function loadEvents(){eventList.innerHTML='<p class="empty">Cargando eventos…</p>';try{const {events}=await api('/api/admin/events');eventList.innerHTML=events.length?events.map(event=>`<article class="event" data-event="${event.id}">${event.image?`<img class="event-image" src="${apiBase}${escapeHtml(event.image)}" alt="">`:''}<div class="event-head"><h3>${escapeHtml(event.name)}</h3><span class="badge ${event.status==='finished'?'finished':''}">${event.status==='finished'?'Finalizado':'Abierto'}</span></div><p class="event-meta">${escapeHtml(dateText(event.startsAt))} · ${event.registered}/${event.capacity} registros · ${event.available} lugares libres</p><p>${escapeHtml(event.description)}</p><div class="event-actions"><button class="button secondary edit-event" data-id="${event.id}" type="button">Editar</button><button class="button secondary attendees-button" data-id="${event.id}" type="button">Ver inscritos (${event.registered})</button><a class="button secondary" href="${apiBase}/api/admin/events/${event.id}/registrations.pdf">Descargar PDF</a><button class="button danger delete-event" data-id="${event.id}" type="button">Eliminar</button></div><div class="attendees hidden" id="attendees-${event.id}"></div></article>`).join(''):'<p class="empty">Todavía no has creado eventos.</p>';
        eventList.querySelectorAll('.edit-event').forEach(button=>button.addEventListener('click',()=>editEvent(events.find(item=>item.id===Number(button.dataset.id)))));
        eventList.querySelectorAll('.attendees-button').forEach(button=>button.addEventListener('click',()=>loadRegistrations(Number(button.dataset.id))));
        eventList.querySelectorAll('.delete-event').forEach(button=>button.addEventListener('click',()=>deleteEvent(Number(button.dataset.id))));
      }catch(error){eventList.innerHTML=`<p class="empty">${escapeHtml(error.message)}</p>`;}}
    function editEvent(event){document.getElementById('form-title').textContent='Editar evento';document.getElementById('edit-id').value=event.id;document.getElementById('existing-image').value=event.image||'';document.getElementById('event-name').value=event.name;document.getElementById('description').value=event.description;document.getElementById('event-date').value=event.startsAt;document.getElementById('capacity').value=event.capacity;document.getElementById('event-status').value=event.status;document.getElementById('save-event').textContent='Guardar cambios';document.getElementById('cancel-edit').classList.remove('hidden');const preview=document.getElementById('image-preview');if(event.image){preview.src=event.image.startsWith('http')?event.image:apiBase+event.image;preview.classList.remove('hidden')}else preview.classList.add('hidden');eventForm.scrollIntoView({behavior:'smooth',block:'start'});}
    function resetForm(){eventForm.reset();document.getElementById('edit-id').value='';document.getElementById('existing-image').value='';document.getElementById('form-title').textContent='Crear evento';document.getElementById('save-event').textContent='Guardar evento';document.getElementById('cancel-edit').classList.add('hidden');document.getElementById('image-preview').classList.add('hidden');document.getElementById('event-image').value='';}
    document.getElementById('cancel-edit').addEventListener('click',resetForm);
    function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('No se pudo leer la imagen.'));reader.readAsDataURL(file);});}
    document.getElementById('event-image').addEventListener('change',async e=>{const file=e.target.files[0];const preview=document.getElementById('image-preview');if(!file){preview.classList.add('hidden');return}if(file.size>5*1024*1024){eventNotice.textContent='La imagen supera 5 MB.';e.target.value='';return}preview.src=URL.createObjectURL(file);preview.classList.remove('hidden');});
    eventForm.addEventListener('submit',async e=>{e.preventDefault();eventNotice.textContent='Guardando…';const save=document.getElementById('save-event');save.disabled=true;try{const file=document.getElementById('event-image').files[0];const body={name:document.getElementById('event-name').value,description:document.getElementById('description').value,startsAt:document.getElementById('event-date').value,capacity:Number(document.getElementById('capacity').value),status:document.getElementById('event-status').value,image:document.getElementById('existing-image').value||null};if(file)body.imageData=await fileAsDataUrl(file);const id=document.getElementById('edit-id').value;await api(id?`/api/admin/events/${id}`:'/api/admin/events',{method:id?'PUT':'POST',body:JSON.stringify(body)});eventNotice.textContent='Evento guardado.';resetForm();await loadEvents()}catch(error){eventNotice.textContent=error.message}finally{save.disabled=false}});
    async function loadRegistrations(id){const panel=document.getElementById(`attendees-${id}`);if(!panel.classList.contains('hidden')){panel.classList.add('hidden');return}panel.classList.remove('hidden');panel.innerHTML='<p class="help">Cargando inscritos…</p>';try{const {registrations}=await api(`/api/admin/events/${id}/registrations`);panel.innerHTML=registrations.length?`<table><thead><tr><th>Nombre</th><th>Teléfono</th><th>Correo</th><th>Fecha de registro</th></tr></thead><tbody>${registrations.map(person=>`<tr><td>${escapeHtml(person.name)}</td><td>${escapeHtml(person.phone)}</td><td>${escapeHtml(person.email||'—')}</td><td>${escapeHtml(person.created_at)}</td></tr>`).join('')}</tbody></table>`:'<p class="help">Aún no hay registros para este evento.</p>'}catch(error){panel.innerHTML=`<p class="help">${escapeHtml(error.message)}</p>`}}
    async function deleteEvent(id){if(!confirm('¿Eliminar este evento y todos sus registros? Esta acción no se puede deshacer.'))return;try{await api(`/api/admin/events/${id}`,{method:'DELETE'});await loadEvents()}catch(error){eventNotice.textContent=error.message}}
    document.getElementById('refresh').addEventListener('click',loadEvents);
    document.getElementById('logout').addEventListener('click',async()=>{await api('/api/logout',{method:'POST',body:'{}'});dashboard.classList.add('hidden');loginPanel.classList.remove('hidden')});
    checkSession();
  </script>
</body>
</html>
